import pandas as pd, numpy as np
from sklearn.linear_model import LinearRegression, RidgeCV
from sklearn.preprocessing import SplineTransformer

df=pd.read_csv('data.csv')
y=df['dY'].values
D=df['D'].values
Tmask=(D>=12)&(D<=14)
num_cols=['log_hist_days','log_pre_gmv','orders','cat_share','tenure']
Xnum=df[num_cols].values
Xcat=pd.get_dummies(df[['region','tier']], columns=['region','tier'], drop_first=True).astype(float).values
Xplace=df[['dY_placebo']].values

class FeatureBuilder:
    def __init__(self, d_spline=True, x_spline=False, n_knots_d=5, n_knots_x=4):
        self.d_spline=d_spline; self.x_spline=x_spline
        self.n_knots_d=n_knots_d; self.n_knots_x=n_knots_x
        self.d_sp=None; self.x_sp=None
    def fit(self, D, Xnum):
        if self.d_spline:
            self.d_sp=SplineTransformer(n_knots=self.n_knots_d, degree=3, include_bias=False).fit(D.reshape(-1,1))
        if self.x_spline:
            self.x_sp=SplineTransformer(n_knots=self.n_knots_x, degree=3, include_bias=False).fit(Xnum)
        return self
    def transform(self, D, Xnum, Xcat, Xplace):
        parts=[]
        if self.d_spline:
            parts.append(self.d_sp.transform(D.reshape(-1,1)))
        else:
            parts.append(D.reshape(-1,1))
        if self.x_spline:
            parts.append(self.x_sp.transform(Xnum))
        else:
            parts.append(Xnum)
        parts.append(Xcat); parts.append(Xplace)
        return np.hstack(parts)

def target_diff_linear(d_spline, x_spline, model='ols'):
    fb=FeatureBuilder(d_spline=d_spline, x_spline=x_spline).fit(D, Xnum)
    Xfull=fb.transform(D, Xnum, Xcat, Xplace)
    if model=='ols':
        m=LinearRegression().fit(Xfull,y)
    else:
        m=RidgeCV(alphas=np.logspace(-3,3,13)).fit(Xfull,y)
    X10=fb.transform(np.full(Tmask.sum(),10.0), Xnum[Tmask], Xcat[Tmask], Xplace[Tmask])
    Xobs=fb.transform(D[Tmask], Xnum[Tmask], Xcat[Tmask], Xplace[Tmask])
    diff=m.predict(X10)-m.predict(Xobs)
    r2=m.score(Xfull,y)
    return diff.mean(), diff, r2, m

for d_spline in [False, True]:
    for x_spline in [False, True]:
        for model in ['ols','ridge']:
            try:
                mean,diff,r2,m=target_diff_linear(d_spline,x_spline,model)
                print(f'd_spline={d_spline} x_spline={x_spline} {model}: diff={mean:.4f} r2={r2:.4f} nfeat={m.n_features_in_}')
            except Exception as e:
                print(e)
